using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Threading;using EffectSystem;using EffectSystem.TF2;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
internal sealed class Tf2Host:EffectResponder {
 sealed class Request:EffectDispatchRequest {public JObject Frame;public string EffectID=>(string)Frame["code"]??"";public TimeSpan RequestedDuration=>TimeSpan.FromMilliseconds(Math.Max(0,Math.Min(600000,(double?)Frame["duration"]??0)));public string Requestor=>(string)Frame["viewer"]??"Viewer";public string Parameter{get{var p=Frame["parameters"];if(p is JArray)return p.First?.ToString()??"";return (p as JObject)?.Properties().FirstOrDefault()?.Value.ToString()??"";}}}
 static readonly TextWriter Protocol;static Tf2Host(){Protocol=Console.Out;}readonly object gate=new object();NetworkStream stream;TF2EffectDispatcher dispatcher;TF2Proxy proxy;
 public static void Main(string[] args){if(args.Length==1&&args[0]=="--catalog"){Console.WriteLine(JsonConvert.SerializeObject(TF2Effects.Instance.CreateAllEffects().Select(e=>e.ID).Distinct().ToArray()));return;}Console.SetOut(TextWriter.Null);ASPEN.Trunk.DefaultConfig(Array.Empty<string>());ASPEN.Trunk.DefaultUserSetting();ASPEN.Trunk.DefaultCommandContext();ASPEN.Aspen.Log=new ASPEN.DefaultLogUtility(TextWriter.Null);new Tf2Host().Run(Path.GetFullPath(args[0]));}
 void Run(string root){string cfg=Path.Combine(root,"tf","cfg");Directory.CreateDirectory(cfg);foreach(var pair in new[]{("autoexec.cfg","exec ShenPulseRCON"),("scout.cfg","setinfo info_class scout;echo __class-scout__"),("soldier.cfg","setinfo info_class soldier;echo __class-soldier__"),("pyro.cfg","setinfo info_class pyro;echo __class-pyro__"),("demoman.cfg","setinfo info_class demoman;echo __class-demoman__"),("heavyweapons.cfg","setinfo info_class heavyweapons;echo __class-heavyweapons__"),("engineer.cfg","setinfo info_class engineer;echo __class-engineer__"),("medic.cfg","setinfo info_class medic;echo __class-medic__"),("sniper.cfg","setinfo info_class sniper;echo __class-sniper__"),("spy.cfg","setinfo info_class spy;echo __class-spy__")}){string file=Path.Combine(cfg,pair.Item1);string old=File.Exists(file)?File.ReadAllText(file):"";if(!old.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Contains(pair.Item2)){string backup=file+".shenpulse-original";if(File.Exists(file)&&!File.Exists(backup))File.Copy(file,backup);File.WriteAllText(file,old+"\r\n"+pair.Item2+"\r\n",new UTF8Encoding(false));}}
 string password=Convert.ToHexString(RandomNumberGenerator.GetBytes(24));try{proxy=PollingCacheTF2Proxy.Create(new TF2Config{ConfigVersion=1,TF2Path=root,RCONPort=58833,RCONPassword=password},()=>{});TF2Effects.Instance.TF2Proxy=proxy;dispatcher=new TF2EffectDispatcher(this);dispatcher.Effects.AddRange(TF2Effects.Instance.CreateAllEffects().GroupBy(e=>e.ID).Select(g=>g.First()));Protocol.WriteLine("SHENPULSE_TF2_READY");Protocol.Flush();Console.CancelKeyPress+=(_,e)=>{e.Cancel=true;Stop();};var stdin=new Thread(()=>{while(Console.ReadLine() is string line)if(line=="stop"){Stop();return;}Stop();}){IsBackground=true};stdin.Start();while(true){try{using(var tcp=new TcpClient()){tcp.Connect("127.0.0.1",58832);stream=tcp.GetStream();var bytes=new List<byte>();var chunk=new byte[4096];int n;while((n=stream.Read(chunk,0,chunk.Length))>0){for(int i=0;i<n;i++){if(chunk[i]!=0){bytes.Add(chunk[i]);if(bytes.Count>65536)throw new InvalidDataException();continue;}if(bytes.Count==0)continue;var frame=JObject.Parse(Encoding.UTF8.GetString(bytes.ToArray()));bytes.Clear();int type=(int?)frame["type"]??1;if(type==255)continue;var request=new Request{Frame=frame};if(type==2){dispatcher.StopEarly(request);Reply(request,0,"Interaction arrêtée.");}else if(type==1)dispatcher.Apply(request);else Reply(request,3,"Test manuel requis en partie.");}}}}catch{stream=null;Thread.Sleep(1000);}}}finally{dispatcher?.Dispose();proxy?.ShutDown();}}
 void Stop(){try{dispatcher?.Dispose();proxy?.ShutDown();}catch{}Environment.Exit(0);}
 void Reply(EffectDispatchRequest r,int status,string message){try{var request=(Request)r;var data=Encoding.UTF8.GetBytes(new JObject{["id"]=request.Frame["id"],["status"]=status,["message"]=message}.ToString(Formatting.None)+"\0");lock(gate){stream?.Write(data,0,data.Length);}}catch{}}
 public void AppliedInstant(EffectDispatchRequest r)=>Reply(r,0,"Interaction appliquée.");public void AppliedFor(EffectDispatchRequest r,TimeSpan d)=>Reply(r,0,"Interaction temporaire appliquée.");public void NotAppliedUnavailable(EffectDispatchRequest r)=>Reply(r,2,"Interaction indisponible.");public void NotAppliedFailed(EffectDispatchRequest r,string m)=>Reply(r,1,"Le jeu a refusé cette interaction.");public void NotAppliedRetry(EffectDispatchRequest r)=>Reply(r,3,"Chargez une carte jouable avant cet effet.");public void NotAppliedWait(EffectDispatchRequest r,TimeSpan t)=>Reply(r,3,"Un effet incompatible est encore en cours.");public void DurationPaused(EffectDispatchRequest r,TimeSpan t){}public void DurationResumed(EffectDispatchRequest r,TimeSpan t){}public void DurationFinished(EffectDispatchRequest r){}public void SetListed(string e,bool x){}public void SetSelectable(string e,bool x){}
}
